  "referralMechanics": [
    {
      "component": "Core loop",
      "design": "Every signup gets a unique link + a visible queue position + leaderboard. Referrals move you up. Position is the primary reward (Robinhood model: ~1M pre-launch signups, 3x viral coefficient, no cash reward)."
    },
    {
      "component": "Double-sided perks",
      "design": "Both referrer and referee get a non-cash perk (earlier access tier, launch fee-discount, status badge, LCX swag). Double-sided programs see ~3x the participation of single-sided."
    },
    {
      "component": "Milestone ladder",
      "design": "Progressive, non-cash: 1 ref = move up; 3 = early-access tier; 10 = 'founding user' badge + higher launch fee discount; 25 = priority support / event invite."
    },
    {
      "component": "First-60-seconds prompt",
      "design": "Confirmation email/screen immediately prompts sharing — the single biggest driver of loop velocity."
    },
    {
      "component": "Anti-sybil",
      "design": "Maturation window: the larger perk unlocks only after the referred user completes KYC and stays active at launch. ML fraud detection; cap referrals; dedupe device/IP."
    },
    {
      "component": "At launch (post-live)",
      "design": "Convert to a fee-based referral (trading-fee discount / rev-share), KYC-gated, min-activity qualified — the Coinbase/Kraken pattern (compliant, not a token giveaway)."
    }
  ],
  "guardrails": [
    {
      "guardrail": "No pre-announced token quid-pro-quo",
      "meaning": "SEC/CFTC (Mar 2026): airdrops with no bargained-for consideration aren't securities, but pre-announced 'do X to earn a token' IS. Keep waitlist rewards non-token / non-cash, or clear with counsel.",
      "riskIfIgnored": "Unregistered securities offering",
      "sourceRefs": [
        "p3_1",
        "p3_8"
      ]
    },
    {
      "guardrail": "FTC endorsement disclosure",
      "meaning": "Every KOL (paid, tokens, or early access) discloses the material connection clearly, before the fold; no guaranteed-return or risk-downplaying language.",
      "riskIfIgnored": "FTC action; reputational",
      "sourceRefs": [
        "p3_6"
      ]
    },
    {
      "guardrail": "No price / return promises",
      "meaning": "Per the LCX narrative: utility not investment. No 'buy now', ROI, or price talk in any waitlist creative.",
      "riskIfIgnored": "Ad-platform rejection; securities/marketing risk",
      "sourceRefs": [
        "p3_7"
      ]
    },
    {
      "guardrail": "Ad-platform certification",
      "meaning": "Google/Meta/X crypto ads need a certified 'Verified Crypto Advertiser' + licensed exchange; buy/sell promos restricted.",
      "riskIfIgnored": "Ads auto-rejected; wasted spend",
      "sourceRefs": [
        "p3_3",
        "p3_4"
      ]
    },
    {
      "guardrail": "Geo / state gating",
      "meaning": "Only invite & convert users in states LCX US can legally serve (ties to Phase 2 licensing). Geoblock others (EEA already geofenced).",
      "riskIfIgnored": "Operating out of licence",
      "sourceRefs": []
    },
    {
      "guardrail": "Data & consent",
      "meaning": "Waitlist email capture with clear consent, privacy policy, CAN-SPAM unsubscribe; store PII per policy.",
      "riskIfIgnored": "Privacy / CAN-SPAM exposure",
      "sourceRefs": []
    }
  ],
